using System.Collections.Generic;
using System.IO;
using ProjectTower.io;
using ProjectTower.player;
using ProjectTower.texturesheet;
namespace LootEdit.loot;
public class LootCatalog
{
	CATEGORY_WEAPON = 0;
	CATEGORY_SHIELD = 1;
	CATEGORY_ARMOR = 2;
	CATEGORY_RING = 3;
	CATEGORY_CONSUMABLE = 4;
	CATEGORY_MAGIC = 5;
	CATEGORY_KEYS = 6;
	CATEGORY_MATERIALS = 7;
	TOTAL_CATEGORIES = 8;
	public static int smallclothesBootsIdx;
	public static int smallclothesArmorIdx;
	public static LootCategory[] category;
	public static LootCategory[] classic;
	public static LootCategory[] enhanced;
	public static void Init()
	{
		category = new LootCategory[8];
		for (int i = 0; i < category.Length; i++)
		{
			category[i] = new LootCategory();
		}
	}
	public static void Read(BinaryReader reader, bool isEnhanced = false)
	{
		for (int i = 0; i < category.Length; i++)
		{
			category[i].Read(reader);
		}
		for (int j = 0; j < category.Length; j++)
		{
			for (int k = 0; k < category[j].loot.Length; k++)
			{
				category[j].loot[k].texIdx = Textures.GetTextureIdx(category[j].loot[k].texture);
				if (j == 2)
				{
