	public static void ReadLoot(string path)
	{
		FileMgr.Open("loot/data" + path + ".zlx");
		Read(FileMgr.reader, isEnhanced: true);
		FileMgr.Close();
	}
	internal static int[] GetCategories(Player p)
	{
		List<int> list = new List<int>();
		for (int i = 0; i < p.playerInv.inventory.Length; i++)
		{
			InvLoot invLoot = p.playerInv.inventory[i];
			if (invLoot == null)
			{
				continue;
			}
			LootDef lootDef = category[invLoot.category].loot[invLoot.catalogIdx];
			if (CanSell(lootDef))
			{
				int num = lootDef.category;
				if ((uint)(num - 5) > 1u && !list.Contains(lootDef.category))
				{
					list.Add(lootDef.category);
				}
			}
		}
		return list.ToArray();
	}
	internal static bool CanSell(LootDef lDef)
	{
		switch (lDef.category)
		{
		case 0:
			if (lDef.type == 15)
			{
				return false;
			}
			break;
		case 3:
			if (lDef.type == 2)
			{
				return false;
			}
			break;
		case 1:
			if (lDef.type == 4)
			{
				return false;
			}
			break;
		case 4:
		{
			int flags = lDef.flags;
			if ((uint)(flags - 1) <= 8u || flags == 68)
			{
				return false;
			}
			break;
		}
		}
		return true;
	}
	internal static int[] GetCategories(string[] loot)
	{
		List<int> list = new List<int>();
		for (int i = 0; i < loot.Length; i++)
		{
			LootDef lootDef = null;
			for (int j = 0; j < category.Length; j++)
			{
				for (int k = 0; k < category[j].loot.Length; k++)
				{
					if (category[j].loot[k].name == loot[i])
					{
						lootDef = category[j].loot[k];
					}
				}
			}
			if (lootDef != null && !list.Contains(lootDef.category))
			{
				list.Add(lootDef.category);
			}
		}
		return list.ToArray();
	}
