	public static float GetCharmAdjustedCost(Character c, int type)
	{
		float num = 1f;
		if (c.equipment.active)
		{
			if (c.stats.GetRingFlag(26) && (uint)type <= 3u)
			{
				num *= 0.9f;
			}
			if (c.stats.GetRingFlag(27) && (uint)(type - 4) <= 1u)
			{
				num *= 0.9f;
			}
			LootDef lootDef = null;
			if (c.equipment.loadout[c.equipment.loadoutIdx, 0].catalogIdx > -1 && c.equipment.loadout[c.equipment.loadoutIdx, 0].catalogIdx < LootCatalog.category[0].loot.Length && c.equipment.loadout[c.equipment.loadoutIdx, 0].catalogIdx < 128 && c.equipment.loadout[c.equipment.loadoutIdx, 0].category != 4)
			{
				lootDef = LootCatalog.category[0].loot[c.equipment.loadout[c.equipment.loadoutIdx, 0].catalogIdx];
			}
			else if (c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx > 128 && c.equipment.loadout[c.equipment.loadoutIdx, 1].invIdx > -1)
			{
				lootDef = LootCatalog.category[0].loot[c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx - 128];
			}
			if (lootDef != null && lootDef.flags == 21 && (type == 0 || type == 2))
			{
				num *= 1.25f;
			}
		}
		return num;
	}
	public static float GetScaledValue(float value, Player p, int scale)
	{
		switch (scale)
		{
		case 0:
			value *= 1f + p.stats.GetCappedStat40(5) * 0.02f;
			if (PlayerMgr.GetMainPlayer().sanctuaryBonus[1])
			{
				value *= 1.1f;
			}
			break;
		case 1:
			value *= 1f + p.stats.GetCappedStat40(4) * 0.02f;
			if (PlayerMgr.GetMainPlayer().sanctuaryBonus[4])
			{
				value *= 1.1f;
			}
			break;
		case 2:
			value *= 1f + p.stats.GetCappedStat40(4, 1f) * 0.01f + p.stats.GetCappedStat40(5, 1f) * 0.01f;
			break;
		case 3:
			value *= 1f + p.stats.GetCappedMinStat40(4, 5) * 0.02f;
			break;
		}
		return value;
	}
