	public static float GetWeightAdjustedRatio(Character c, int type)
	{
		float num = 1f;
		switch (type)
		{
		case 0:
		case 1:
		case 2:
		case 3:
			num *= c.stats.GetWeightPerc(null) * 0.65f + 0.35f;
			break;
		case 4:
		case 5:
			num *= (1f - c.stats.GetWeightPerc(null)) * 0.5f + 0.5f;
			break;
		}
		return num;
	}
