	public struct UpgradePath(string reqLoot, string outLoot, int cost, int reqCount)
	{
		public string reqLoot = reqLoot;
		public string outLoot = outLoot;
		public int cost = cost;
		public int reqCount = reqCount;
		internal void Write(BinaryWriter writer)
		{
			if (reqLoot == null || outLoot == null || reqLoot == "" || outLoot == "")
			{
				writer.Write(value: false);
				return;
			}
			writer.Write(value: true);
			writer.Write(reqLoot);
			writer.Write(reqCount);
			writer.Write(outLoot);
			writer.Write(cost);
		}
		internal void Read(BinaryReader reader)
		{
			if (reader.ReadBoolean())
			{
				reqLoot = reader.ReadString();
				reqCount = reader.ReadInt32();
				outLoot = reader.ReadString();
				cost = reader.ReadInt32();
			}
		}
	}
