	internal float GetWeaponBladeFactor()
	{
		float num = 0f;
		switch (type)
		{
		case 0:
		case 1:
		case 4:
		case 5:
		case 11:
		case 13:
		case 18:
		case 19:
		case 20:
		case 21:
			num = 1f;
			break;
		case 2:
		case 7:
			num = 0f;
			break;
		case 3:
		case 12:
			num = 0.5f;
			break;
		case 6:
		case 17:
			num = 0.75f;
			break;
		case 8:
			num = 0.8f;
			if (GameModeMgr.IsGameEnhanced())
			{
				num = 1f;
			}
			break;
		case 9:
			num = 0.9f;
			if (GameModeMgr.IsGameEnhanced())
			{
				num = 0.75f;
			}
			break;
		case 14:
			num = 0.5f;
			break;
		}
		switch (special)
		{
		case 4:
			num += (1f - num) * 0.5f;
			break;
		case 3:
		case 10:
			num *= 0.5f;
			break;
		case 9:
		case 11:
			num = 0f;
			break;
		case 12:
			num = 1f;
			break;
		}
		return num;
	}
	internal bool IsWeaponMundane()
	{
		if (category != 0)
		{
			return false;
		}
		int num = flags;
		if ((uint)(num - 1) <= 2u || (uint)(num - 5) <= 1u)
		{
			return false;
		}
		return true;
	}
}

