public class ArmorStats
{
	public float[][] defense;
	public const int PHYSICAL = 0;
	public const int FIRE = 1;
	public const int LIGHTNING = 2;
	public const int POISON = 3;
	public const int FROST = 4;
	public const int MAGIC = 5;
	public const int TOTAL_STATS = 6;
	public ArmorStats(float[] physicalDefense, float[] fireDefense, float[] lightningDefense, float[] poisonDefense, float[] frostDefense, float[] magicDefense)
	{
		defense = new float[6][];
		defense[0] = physicalDefense;
		defense[1] = fireDefense;
		defense[2] = lightningDefense;
		defense[3] = poisonDefense;
		defense[4] = frostDefense;
		defense[5] = magicDefense;
	}
	public float GetReducedDamage(float damage, int type, int defLevel)
	{
		float def = defense[type][defLevel];
		return GetReducedDamage(damage, def);
	}
	public static float GetReducedDamage(float damage, float def)
	{
		while (true)
		{
			if (damage == 0f)
			{
				return damage;
			}
			if (def < damage / 4f)
			{
				break;
			}
			def -= damage / 4f;
			damage -= damage / 4f;
			def /= 3f;
		}
		damage -= def;
		return damage;
	}
}
