		public void SetForNPC(int category, string item)
		{
			if (item == "")
			{
				catalogIdx = -1;
				invIdx = -1;
				return;
			}
			if (item.Contains('/'))
			{
				try
				{
					item = item.Split('/')[0];
				}
				catch
				{
					return;
				}
			}
			if (category == -1)
			{
				for (int i = 0; i < LootCatalog.category.Length; i++)
				{
					for (int j = 0; j < LootCatalog.category[i].loot.Length; j++)
					{
						if (LootCatalog.category[i].loot[j].name == item)
						{
							category = i;
							break;
						}
					}
					if (category > -1)
					{
						break;
					}
				}
			}
			if (category <= -1)
			{
				return;
			}
			for (int k = 0; k < LootCatalog.category[category].loot.Length; k++)
			{
				if (LootCatalog.category[category].loot[k].name == item)
				{
					this.category = category;
					catalogIdx = k;
					invIdx = -1;
					break;
				}
			}
		}
		public void SetFromInventory(int invIndex, Character c)
		{
			if (c.playerIdx >= 0)
			{
				Player player = PlayerMgr.player[c.playerIdx];
				invIdx = invIndex;
				catalogIdx = player.playerInv.inventory[invIdx].catalogIdx;
				category = player.playerInv.inventory[invIdx].category;
				player.playerInv.RefreshEquipped();
			}
		}
		public void Remove(Character c)
		{
			invIdx = -1;
			catalogIdx = -1;
			category = -1;
			PlayerMgr.player[c.playerIdx].playerInv.RefreshEquipped();
		}
		public void SetAndAddToInventory(int category, string item, Character c, bool canDupe)
		{
			if (c.playerIdx < 0)
			{
				return;
			}
			if (item == "")
			{
				invIdx = -1;
				catalogIdx = -1;
				this.category = -1;
				return;
			}
			int count = 1;
			if (item.Contains('/'))
			{
				try
				{
					string[] array = item.Split('/');
					item = array[0];
					count = Convert.ToInt32(array[1]);
				}
				catch
				{
					return;
				}
			}
			Player player = PlayerMgr.player[c.playerIdx];
			if (category == -1)
			{
				for (int i = 0; i < LootCatalog.category.Length; i++)
				{
					for (int j = 0; j < LootCatalog.category[i].loot.Length; j++)
					{
						if (LootCatalog.category[i].loot[j].name == item)
						{
							category = i;
							break;
						}
					}
					if (category > -1)
					{
						break;
					}
				}
			}
			for (int k = 0; k < LootCatalog.category[category].loot.Length; k++)
			{
				if (LootCatalog.category[category].loot[k].name == item)
				{
					catalogIdx = k;
					this.category = category;
					InvLoot invLoot = new InvLoot();
					invLoot.InitFromName(item);
					invIdx = -1;
					if (!canDupe)
					{
						invIdx = player.playerInv.Match(invLoot);
					}
					if (invIdx == -1)
					{
						invIdx = player.playerInv.Add(invLoot, autoSelect: true, count);
					}
					player.playerInv.RefreshEquipped();
					return;
				}
			}
			if (category != 4)
			{
				return;
			}
			category = 5;
			for (int l = 0; l < LootCatalog.category[category].loot.Length; l++)
			{
				if (LootCatalog.category[category].loot[l].name == item)
				{
					catalogIdx = l;
					this.category = category;
					InvLoot invLoot2 = new InvLoot();
					invLoot2.InitFromName(item);
					invIdx = player.playerInv.Add(invLoot2, autoSelect: true, count);
					player.playerInv.RefreshEquipped();
					break;
				}
			}
		}
		internal void Write(BinaryWriter writer)
		{
			writer.Write(catalogIdx);
			writer.Write(category);
			writer.Write(invIdx);
		}
		internal void Read(BinaryReader reader)
		{
			catalogIdx = reader.ReadInt32();
			category = reader.ReadInt32();
			invIdx = reader.ReadInt32();
		}
