public Point GetAvailableLoadoutSlot(LootDef lDef)
{
	for (int i = 0; i < 2; i++)
	{
		for (int j = 1; j < 3; j++)
		{
			if (CanEquipLootInLoadoutSlot(i, j, lDef))
			{
				return new Point(i, j);
			}
		}
	}
	return new Point(-1, -1);
}
public Point GetNextAvailableLoadoutSlot(int loadoutIdx, int slotIdx, LootDef lDef)
{
	int x = loadoutIdx;
	int y = slotIdx;
	do
	{
		slotIdx++;
		if (slotIdx > 2)
		{
			slotIdx = 0;
			loadoutIdx++;
			if (loadoutIdx > 1)
			{
				return new Point(x, y);
			}
		}
	}
	while (!CanEquipLootInLoadoutSlot(loadoutIdx, slotIdx, lDef));
	return new Point(loadoutIdx, slotIdx);
}
public Point GetPreviousAvailableLoadoutSlot(int loadoutIdx, int slotIdx, LootDef lDef)
{
	int x = loadoutIdx;
	int y = slotIdx;
	do
	{
		slotIdx--;
		if (slotIdx < 0)
		{
			slotIdx = 2;
			loadoutIdx--;
			if (loadoutIdx < 0)
			{
				return new Point(x, y);
			}
		}
	}
	while (!CanEquipLootInLoadoutSlot(loadoutIdx, slotIdx, lDef));
	return new Point(loadoutIdx, slotIdx);
}
internal bool CanAttack(int attackIdx)
{
	if (c.playerIdx > -1)
	{
		Player player = c.GetPlayer();
		if (player != null)
		{
			if (loadout[loadoutIdx, attackIdx].catalogIdx - 128 > -1 && loadout[loadoutIdx, attackIdx].catalogIdx - 128 < LootCatalog.category[0].loot.Length)
			{
				LootDef lootDef = LootCatalog.category[0].loot[loadout[loadoutIdx, attackIdx].catalogIdx - 128];
				if (lootDef.type == 14 || lootDef.type == 9)
				{
					return true;
				}
			}
			if (loadout[loadoutIdx, 0].catalogIdx > -1 && loadout[loadoutIdx, 0].catalogIdx < LootCatalog.category[0].loot.Length)
			{
				LootDef lootDef2 = LootCatalog.category[0].loot[loadout[loadoutIdx, 0].catalogIdx];
				switch (player.challenge.category[1].activeChallenge)
				{
				case 2:
					if (lootDef2.name != "spear_oar")
					{
						return false;
					}
					break;
				case 1:
					if (lootDef2.name != "mace_pot")
					{
						return false;
					}
					break;
				case 0:
				{
					int type = lootDef2.type;
					if (type != 10 && type != 16)
					{
						return false;
					}
					break;
				}
				}
				switch (lootDef2.type)
				{
				case 10:
					if (player.stats.Equippable(lootDef2, -1) == 0)
					{
						return false;
					}
					if (loadout[loadoutIdx, attackIdx + 1].catalogIdx > -1 && loadout[loadoutIdx, attackIdx + 1].catalogIdx < LootCatalog.category[5].loot.Length)
					{
						LootDef lootDef3 = LootCatalog.category[5].loot[loadout[loadoutIdx, attackIdx + 1].catalogIdx];
						return player.stats.Equippable(lootDef3, -1) == 2;
					}
					return false;
				case 8:
					if (c.equipment.loadout[loadoutIdx, attackIdx + 1].catalogIdx < 0)
					{
						return false;
					}
					if (c.equipment.loadout[loadoutIdx, attackIdx + 1].invIdx < 0)
					{
						return false;
					}
					if (player.playerInv.inventory[c.equipment.loadout[loadoutIdx, attackIdx + 1].invIdx] == null)
					{
						return false;
					}
					if (player.playerInv.inventory[c.equipment.loadout[loadoutIdx, attackIdx + 1].invIdx].count <= 0)
					{
						return false;
					}
					return player.stats.Equippable(lootDef2, -1) == 2;
				default:
				{
					int num = player.stats.Equippable(lootDef2, -1);
					if (num == 0)
					{
						return false;
					}
					if (LootCatalog.category[0].loot[loadout[loadoutIdx, 0].catalogIdx].type == 18 && twoHanded[c.equipment.loadoutIdx] && attackIdx == 1)
					{
						if (c.equipment.loadout[loadoutIdx, attackIdx].catalogIdx < 0)
						{
							if (c.anim.animName == "dlattack")
							{
								return true;
							}
							return false;
						}
						if (c.equipment.loadout[loadoutIdx, attackIdx].invIdx < 0)
						{
							return false;
						}
						if (player.playerInv.inventory[c.equipment.loadout[loadoutIdx, attackIdx].invIdx].count <= 0)
						{
							return false;
						}
					}
					if (num == 1)
					{
						return twoHanded[c.equipment.loadoutIdx];
					}
					return true;
				}
				}
			}
		}
	}
	return true;
}
