internal void Write(BinaryWriter writer)
{
	helm.Write(writer);
	armor.Write(writer);
	gloves.Write(writer);
	boots.Write(writer);
	for (int i = 0; i < 2; i++)
	{
		for (int j = 0; j < 3; j++)
		{
			loadout[i, j].Write(writer);
		}
	}
	for (int k = 0; k < consumable.Length; k++)
	{
		consumable[k].Write(writer);
	}
	for (int l = 0; l < incantation.Length; l++)
	{
		incantation[l].Write(writer);
	}
	for (int m = 0; m < ring.Length; m++)
	{
		ring[m].Write(writer);
	}
	for (int n = 0; n < 2; n++)
	{
		writer.Write(twoHanded[n]);
	}
	writer.Write(selConsumable);
	writer.Write(selIncantation);
	writer.Write(selectedUseRow);
	writer.Write(loadoutIdx);
}
internal void Read(BinaryReader reader)
{
	helm.Read(reader);
	armor.Read(reader);
	gloves.Read(reader);
	boots.Read(reader);
	for (int i = 0; i < 2; i++)
	{
		for (int j = 0; j < 3; j++)
		{
			loadout[i, j].Read(reader);
		}
	}
	for (int k = 0; k < consumable.Length; k++)
	{
		consumable[k].Read(reader);
	}
	for (int l = 0; l < incantation.Length; l++)
	{
		incantation[l].Read(reader);
	}
	for (int m = 0; m < ring.Length; m++)
	{
		ring[m].Read(reader);
	}
	for (int n = 0; n < 2; n++)
	{
		twoHanded[n] = reader.ReadBoolean();
	}
	selConsumable = reader.ReadInt32();
