internal void InitFromString(string s)
{
	try
	{
		if (s.Length >= 26)
		{
			loadoutIdx = 0;
			hair = SteamDataConversion.StringToInt16(s, 0) - 1;
			hairColor = SteamDataConversion.StringToInt16(s, 2) - 1;
			beard = SteamDataConversion.StringToInt16(s, 4) - 1;
			beardColor = SteamDataConversion.StringToInt16(s, 6) - 1;
			skinIdx = SteamDataConversion.StringToInt16(s, 8) - 1;
			skinClass = SteamDataConversion.StringToInt16(s, 10) - 1;
			eyeColor = SteamDataConversion.StringToInt16(s, 12) - 1;
			helm.category = 2;
			armor.category = 2;
			gloves.category = 2;
			boots.category = 2;
			helm.catalogIdx = SteamDataConversion.StringToInt16(s, 14) - 1;
			armor.catalogIdx = SteamDataConversion.StringToInt16(s, 16) - 1;
			gloves.catalogIdx = SteamDataConversion.StringToInt16(s, 18) - 1;
			boots.catalogIdx = SteamDataConversion.StringToInt16(s, 20) - 1;
			loadout[loadoutIdx, 0].catalogIdx = SteamDataConversion.StringToInt16(s, 22) - 1;
			loadout[loadoutIdx, 1].catalogIdx = SteamDataConversion.StringToInt16(s, 24) - 1;
			loadout[loadoutIdx, 0].category = 0;
			loadout[loadoutIdx, 1].category = ((loadout[loadoutIdx, 1].catalogIdx < 128) ? 1 : 0);
			if (hair >= HairCatalog.hairType.Length)
			{
